files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1e1e2f;
  color: #f0f0f0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 420px;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: #f9c74f;
}

.subtitle {
  font-size: 1rem;
  color: #c0c0d0;
  margin-bottom: 20px;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 20px;
}

.tile {
  aspect-ratio: 1;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, outline 0.1s;
  font-size: 0;
  padding: 0;
  position: relative;
}

.tile:hover,
.tile:focus-visible {
  transform: scale(1.05);
  box-shadow: 0 0 0 3px #f9c74f;
  outline: none;
  z-index: 1;
}

.tile:active {
  transform: scale(0.95);
}

.tile.selected {
  box-shadow: 0 0 0 4px #f9c74f;
  transform: scale(1.05);
  z-index: 2;
}

.tile[data-color="0"] { background: #e63946; }
.tile[data-color="1"] { background: #f4a261; }
.tile[data-color="2"] { background: #2a9d8f; }
.tile[data-color="3"] { background: #457b9d; }

.status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding: 0 4px;
  font-size: 1.125rem;
}

#swapCount {
  color: #c0c0d0;
}

.solved {
  color: #f9c74f;
  font-weight: 700;
  font-size: 1.25rem;
}

.button {
  background: #f9c74f;
  color: #1e1e2f;
  border: none;
  border-radius: 12px;
  padding: 14px 32px;
  font-size: 1.125rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
}

.button:hover,
.button:focus-visible {
  background: #f9844a;
  outline: 3px solid #f9c74f;
  outline-offset: 2px;
}

.button:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .board {
    gap: 6px;
  }
  .tile {
    border-radius: 8px;
  }
}

const COLORS = 4;
const SIZE = 4;

let grid = [];
let swaps = 0;
let selected = null;
const boardEl = document.getElementById('board');
const swapCountEl = document.getElementById('swapCount');
const solvedEl = document.getElementById('solvedMessage');
const shuffleBtn = document.getElementById('shuffleBtn');

function createGrid() {
  const arr = [];
  for (let r = 0; r < SIZE; r++) {
    const row = [];
    for (let c = 0; c < SIZE; c++) {
      row.push(Math.floor(r * SIZE / SIZE));
    }
    arr.push(row);
  }
  return arr;
}

function shuffleGrid() {
  const flat = [];
  for (let i = 0; i < SIZE * SIZE; i++) {
    flat.push(Math.floor(i / SIZE));
  }
  for (let i = flat.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [flat[i], flat[j]] = [flat[j], flat[i]];
  }
  const newGrid = [];
  for (let r = 0; r < SIZE; r++) {
    newGrid.push(flat.slice(r * SIZE, (r + 1) * SIZE));
  }
  return newGrid;
}

function isSolved() {
  for (let r = 0; r < SIZE; r++) {
    const first = grid[r][0];
    for (let c = 1; c < SIZE; c++) {
      if (grid[r][c] !== first) return false;
    }
  }
  return true;
}

function render() {
  boardEl.innerHTML = '';
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'tile';
      btn.dataset.color = grid[r][c];
      btn.dataset.row = r;
      btn.dataset.col = c;
      btn.setAttribute('aria-label', `Row ${r + 1} column ${c + 1}, color ${grid[r][c]}`);
      btn.setAttribute('role', 'gridcell');
      if (selected && selected.r === r && selected.c === c) {
        btn.classList.add('selected');
      }
      btn.addEventListener('click', onTileClick);
      boardEl.appendChild(btn);
    }
  }
  swapCountEl.textContent = `Swaps: ${swaps}`;
  solvedEl.hidden = !isSolved();
}

function onTileClick(e) {
  const btn = e.currentTarget;
  const r = +btn.dataset.row;
  const c = +btn.dataset.col;
  if (!selected) {
    selected = { r, c };
    render();
    return;
  }
  if (selected.r === r && selected.c === c) {
    selected = null;
    render();
    return;
  }
  const dr = Math.abs(selected.r - r);
  const dc = Math.abs(selected.c - c);
  if (dr + dc === 1) {
    [grid[selected.r][selected.c], grid[r][c]] = [grid[r][c], grid[selected.r][selected.c]];
    swaps++;
    selected = null;
    render();
  } else {
    selected = { r, c };
    render();
  }
}

function startGame() {
  grid = shuffleGrid();
  swaps = 0;
  selected = null;
  render();
}

shuffleBtn.addEventListener('click', startGame);

startGame();
